import { BrowserRouter, Route, Routes } from "react-router-dom"
import { About, Main } from "../../pages"

export const AppRoutes = () => {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Main />} />
        <Route path="/about" element={<About />} />
      </Routes>
    </BrowserRouter>
  )
}